        add(stage,'learn','เรียนรู้: '+t['title'],t['concept']+' · อธิบายความหมาย หลักคิด เหตุผล และข้อจำกัด 2–3 ย่อหน้าสั้น; ตัวอย่าง: '+t['example'],'อ่าน/ฟัง แตะดูตัวอย่างจำลองแล้วค่อยรับภารกิจ','ตัวอย่างคนละสถานการณ์กับภารกิจและข้อสอบ; คำสั้นสำหรับเด็กพร้อมคำอธิบายวิชาการ',['reuse:techno-read']+scene+props,2)
