    add(post,'unit-post','ลองเองหลังเรียน',prepost[n-1][1],'4 ข้อ/งานย่อยใหม่ ไม่มีคำใบ้ระหว่างประเมิน ให้ทบทวนเมื่อส่งครบ','เก็บหลังครั้งแรกและครั้งล่าสุดแยกกัน; เต็ม 4 เช่นก่อนเรียน',['reuse:techno-think']+props,5)
    add(reflect,'reflect','เล่าให้ Techno ฟัง','ฉันทำได้เรื่องใด / แก้ตรงไหน / อยากฝึกอะไร · ครูถามเหตุผลสั้น','เลือกภาพสะท้อน 3 ตัวเลือกและชี้/เล่า ไม่บังคับพิมพ์','ความรู้สึกไม่ใช่คะแนนวิชาการ ครูยืนยันหลักฐานการเล่า',['reuse:techno-reward','reuse:techno-think','reuse:techno-present'],3)
    add(boss,'boss','คืนพลังให้สถานี',bossgames[n-1],'Phaser; รอบสั้น 60–90 วินาที ฝึกช้า หยุด เสียง ข้ามได้','คะแนนเกมแยกจากแบบทดสอบ แพ้ไม่ลบผลการเรียน',['reuse:boss-u'+str(n),'reuse:rider-shooter']+[a['assetId'] for a in assets if n in a['units'] and a['batch']=='A08'],2)
