    for j,p in enumerate(pages):p['pageNumber']=j+1;p['nextPageId']=pages[j+1]['pageId'] if j+1<len(pages) else None
    u=dict(unitId=f'u{n:02}',number=n,academicTitle=source['new'],guideTitle=source['old'],missionTitle=missions[n-1],guidePdfPages=source['pdf'],objectives=source['obj'],topics=topics,stages=summary,pageCount=len(pages),endIndicators=[f'ว 4.2 ป.1/{x}' for x in source['orig'] if x!=3],interimIndicators=['ว 4.2 ป.1/3'] if 3 in source['orig'] else [],addedEndIndicators=[f'ว 4.2 ป.1/{x}' for x in source['link']],proposedHours=3 if n in [4,9] else 2,bossFile=bosses[n-1],realTask=real_tasks[n-1],newAssetRefs=refs,pages=pages)
