    for p in pages:
        md += [f"### หน้า {p['pageNumber']:02} · {p['pageId']} · {p['title']}",f"- ด่าน {p['stageNumber']} / ช่วง `{p['phase']}`",'- มีอะไร: '+p['content'],'- ทำอะไร: '+p['interaction'],'- ตรวจ/เก็บหลักฐาน: '+p['successCriteria'],'- ภาพ: '+', '.join(p['assetRefs'])]
    md += ['## ขอบเขตงานภาพและเกม',f"บอสใช้ `{u['bossFile']}` จากคลังเดิม ตรวจภาพจริงและ mapping ท่าก่อนใช้ ไม่สมมติว่า index ของทุกตัวเหมือน Golden Parasite",'ไฟล์ภาพที่จะสร้างใหม่: '+(', '.join(refs) or 'ไม่มีชุดใหม่บังคับ ใช้ภาพ v4 เดิม'), 'ดู 03_ทะเบียนภาพและคำสั่งสร้าง.md สำหรับคำอธิบายทุก assetId และ 04_สัญญาการพัฒนา_AI.md สำหรับการบันทึก/คะแนน/เกณฑ์ส่งมอบ']
    (out/f"บท{n:02}_{missions[n-1]}.md").write_text('\n\n'.join(md)+'\n','utf-8')

